#!/usr/bin/env python3
"""Minimal OpenCV camera publisher for the DOFBOT color-sorting pipeline."""

import cv2
import rclpy
from cv_bridge import CvBridge
from rclpy.node import Node
from sensor_msgs.msg import Image


class CameraPublisher(Node):
    def __init__(self):
        super().__init__('dofbot_camera')
        self.declare_parameter('video_device', '/dev/video2')
        self.declare_parameter('image_width', 640)
        self.declare_parameter('image_height', 480)
        self.declare_parameter('framerate', 10.0)

        device = self.get_parameter('video_device').value
        width = int(self.get_parameter('image_width').value)
        height = int(self.get_parameter('image_height').value)
        fps = float(self.get_parameter('framerate').value)

        self.capture = cv2.VideoCapture(device, cv2.CAP_V4L2)
        self.capture.set(cv2.CAP_PROP_FRAME_WIDTH, width)
        self.capture.set(cv2.CAP_PROP_FRAME_HEIGHT, height)
        self.capture.set(cv2.CAP_PROP_FPS, fps)
        if not self.capture.isOpened():
            raise RuntimeError(f'Cannot open camera {device}')

        self.bridge = CvBridge()
        self.publisher = self.create_publisher(Image, '/image_raw', 1)
        self.timer = self.create_timer(1.0 / max(fps, 1.0), self.publish_frame)
        self.get_logger().info(
            f'Publishing {device} at {width}x{height}, {fps:.1f} FPS on /image_raw')

    def publish_frame(self):
        ok, frame = self.capture.read()
        if not ok:
            self.get_logger().error('Camera frame read failed', throttle_duration_sec=2.0)
            return
        msg = self.bridge.cv2_to_imgmsg(frame, encoding='bgr8')
        msg.header.stamp = self.get_clock().now().to_msg()
        msg.header.frame_id = 'camera_link'
        self.publisher.publish(msg)

    def destroy_node(self):
        self.capture.release()
        super().destroy_node()


def main(args=None):
    rclpy.init(args=args)
    node = None
    try:
        node = CameraPublisher()
        rclpy.spin(node)
    except KeyboardInterrupt:
        pass
    finally:
        if node is not None:
            node.destroy_node()
        if rclpy.ok():
            rclpy.shutdown()


if __name__ == '__main__':
    main()
